.formio-component-datagrid .formio-button-remove-row .fa-times-circle-o::before {
  content: "\f057" !important;
  font-family: "Font Awesome 6 Free", "Font Awesome 5 Free", "FontAwesome" !important;
  font-weight: 900 !important;
}

/* Estilo del botón para que combine con la UI */
.formio-component-datagrid .formio-button-remove-row {
  background-color: transparent !important;
  border: 1px solid #dc3545 !important;
  color: #dc3545 !important;
  width: 36px !important;
  height: 36px !important;
  padding: 0 !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  border-radius: 4px !important;
  transition: all 0.15s ease !important;
  box-shadow: none !important;
}

.formio-component-datagrid .formio-button-remove-row:hover {
  background-color: #dc3545 !important;
  color: #fff !important;
}

.formio-component-datagrid .formio-button-remove-row:focus,
.formio-component-datagrid .formio-button-remove-row:active {
  outline: none !important;
  box-shadow: 0 0 0 2px rgba(220, 53, 69, 0.25) !important;
}

.formio-component-datagrid .formio-button-remove-row i {
  font-size: 16px !important;
  font-family: "Font Awesome 6 Free", "Font Awesome 5 Free", "FontAwesome" !important;
  font-weight: 900 !important;
  font-style: normal !important;
  color: inherit !important;
}
.formio-button-remove-row.btn-secondary {
  background: #c8ced3 !important; /* color original de Bootstrap btn-secondary */
  border-color: #c8ced3 !important;
  color: #23282c !important;
}
.formio-button-remove-row i {
  color: white !important;
}
